int hidp_setup_hid_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
	struct hid_device *hid_dev;
	int ret = -ENOMEM;

	hid_dev = kzalloc(sizeof(*hid_dev), GFP_KERNEL);
	if (!hid_dev)
		goto err;

	session->hid_dev = hid_dev;

	if (copy_from_user(&hid_dev->rd_data, &req->rd_data, sizeof(hid_dev->rd_data))) {
		ret = -EFAULT;
		goto err_free_hid_dev;
	}

	hid_dev->vendor = req->vendor;
	hid_dev->product = req->product;
	hid_dev->country = req->country;

	if (hid_is_blacklisted(hid_dev)) {
		ret = -EPERM;
		goto err_free_hid_dev;
	}

	return 0;

err_free_hid_dev:
	kfree(hid_dev);
err:
	return ret;
}

int hidp_init_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
    int ret = -ENOMEM;

    session->hid_dev = hid_allocate_device();
    if (!session->hid_dev)
        return -ENOMEM;

    session->hid_dev->vendor = req->vendor;
    session->hid_dev->product = req->product;
    session->hid_dev->version = req->version;
    session->hid_dev->country = req->country;
    session->hid_dev->phys = kstrdup(req->phys, GFP_KERNEL);
    if (!session->hid_dev->phys)
        goto err_free_dev;

    session->hid_dev->driver = &hidp_hid_driver;

    ret = hid_dev_register(session->hid_dev);
    if (ret)
        goto err_free_phys;

    ret = hidp_setup_input_devices(session);
    if (ret)
        goto err_unregister_dev;

    session->read_buffer = kmalloc(HIDP_MAX_HID_PACKET, GFP_KERNEL);
    if (!session->read_buffer) {
        ret = -ENOMEM;
        goto err_cleanup_inputs;
    }

    if (hidp_check_blacklist(req->vendor, req->product)) {
        ret = -EPERM;
        goto err_free_buffer;
    }

    return 0;

err_free_buffer:
    kfree(session->read_buffer);
err_cleanup_inputs:
    hidp_cleanup_input_devices(session);
err_unregister_dev:
    hid_dev_unregister(session->hid_dev);
err_free_phys:
    kfree(session->hid_dev->phys);
err_free_dev:
    kfree(session->hid_dev);
    return ret;
}

int hidp_init_session(struct hidp_session *session, struct hidp_connadd_req *req) {
    int ret = -ENOMEM;

    session->hid_dev = hid_allocate_device();
    if (!session->hid_dev)
        return -ENOMEM;

    session->hid_dev->vendor = req->vendor;
    session->hid_dev->product = req->product;
    session->hid_dev->version = req->version;
    session->hid_dev->country = req->country;

    if (copy_from_user(session->hid_dev->dev_rsize, req->data, req->size)) {
        ret = -EFAULT;
        goto err_free_dev;
    }

    session->hid_dev->dev_size = req->size;
    session->hid_dev->driver_data = session;

    ret = hid_add_device(session->hid_dev);
    if (ret < 0)
        goto err_free_dev;

    if (hid_dev_blacklisted(session->hid_dev)) {
        ret = -ENODEV;
        goto err_remove_dev;
    }

    return 0;

err_remove_dev:
    hid_remove_device(session->hid_dev);
err_free_dev:
    hid_free_device(session->hid_dev);
    return ret;
}

int hidp_setup_hid_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
	struct hid_device *hdev;

	session->hid_dev = hdev = hid_allocate_device();
	if (!hdev)
		return -ENOMEM;

	hdev->vendor = req->vendor;
	hdev->product = req->product;
	hdev->version = req->version;
	hdev->country = req->country;
	hdev->driver_data = session;

	if (hid_is_blacklist(hdev)) {
		hid_free_device(hdev);
		return -ENODEV;
	}

	session->hid_read_data = kmalloc(req->max_resolution, GFP_KERNEL);
	if (!session->hid_read_data) {
		hid_free_device(hdev);
		return -ENOMEM;
	}

	if (copy_from_user(session->hid_read_data, req->data, req->data_len)) {
		kfree(session->hid_read_data);
		hid_free_device(hdev);
		return -EFAULT;
	}

	return 0;
}

int hidp_setup_session(struct hidp_session *session, struct hidp_connadd_req *req)
{
	struct hid_device *hid;
	int err;

	hid = hid_allocate_device();
	if (!hid)
		return -ENOMEM;

	session->hid = hid;
	hid->driver_data = session;

	hid->ll_driver = &hidp_hid_ll_driver;
	hid->ll_protocol = HID_LL_KEYBOARD;

	hid->vendor = req->vendor;
	hid->product = req->product;
	hid->version = req->version;
	hid->country = req->country;

	hid->report_length = req->report_length;
	hid->devnum = req->devnum;
	hid->suggested_id = req->suggested_id;

	err = hid_set_field(hid, HID_INPUT_REPORT, 0, req->rd_data, req->rd_size);
	if (err)
		goto err_free_hid;

	if (hidp_is_blacklisted(hid)) {
		err = -ENODEV;
		goto err_free_hid;
	}

	err = hid_register_device(hid);
	if (err)
		goto err_free_hid;

	return 0;

err_free_hid:
	hid_destroy_device(hid);
	return err;
}
